package openquests.custom

import de.westnordost.streetcomplete.data.osm.mapdata.Element
import de.westnordost.streetcomplete.data.osm.mapdata.MapDataWithGeometry

/**
 * A custom StreetComplete quest whose `getApplicableElements(mapData)` needs the surrounding map data
 * (crossings of ways, kerbs, entrances on building outlines...), so it cannot be decided one element
 * at a time like a [CustomQuest].
 *
 * The ports are generated by `engine/port_area_quests.py` into `src/main/kotlin/ported/`, in SC's own
 * packages: the quest's filters, helpers and `getApplicableElements()` verbatim. The engine runs them
 * the way the app's `OsmQuestController.createQuestsForBBox` does on a downloaded area: on one
 * `MapDataWithGeometry` per city (see AreaPass), keeping the results whose position is inside it.
 */
interface AreaQuest {
    /** SC's quest type name, as in the registry dump */
    val name: String
    /** whether the kept code mentions the clock (`older`, `today`, `TagOlderThan`...); agedOnly is
     *  computed for every area quest regardless */
    val usesAge: Boolean
    fun getApplicableElements(mapData: MapDataWithGeometry): Iterable<Element>
}
